request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
unary-011

Cluster Arity:
1

Cluster Members:
[
  {
    "name": "PLANS_NEXT_ACTION",
    "definition": "The reasoning explicitly expresses an intended future action or sequence of actions that the agent has not yet performed.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that states an intended future action or sequence."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one intended future action or step.",
      "The intended action is presented as something still to be done rather than as already completed."
    ],
    "exclusion_conditions": [
      "The reasoning only reports or summarizes actions already completed.",
      "The reasoning states a conclusion, diagnosis, or observation summary without expressing future intent.",
      "The reasoning states only a general goal or desired result without identifying any intended action or step."
    ]
  },
  {
    "name": "DECOMPOSES_TASK_INTO_SUBGOALS",
    "definition": "The reasoning breaks an overall task into two or more distinct subgoals, questions, or procedural steps that stand in an ordering or dependency relationship and can guide subsequent execution.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that decomposes the overall task into subgoals or procedural steps."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least two distinct subgoals, questions, or procedural steps.",
      "The subgoals or steps are presented with an ordering, dependency, or execution relationship rather than as an unrelated collection.",
      "The decomposition is derived from the stated task and is specific enough to guide execution."
    ],
    "exclusion_conditions": [
      "The reasoning identifies only a single intended action or subgoal.",
      "The reasoning merely restates the overall task without dividing it into executable parts.",
      "The reasoning lists unrelated facts or observations that are not presented as parts of the task."
    ]
  },
  {
    "name": "DIAGNOSES_ROOT_CAUSE",
    "definition": "The reasoning reconstructs a causal account of how an observed state came to be, specifying the preceding events or actions responsible for it rather than merely restating what the state is.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node presenting the causal reconstruction of the observed state."
      }
    ],
    "assertion_conditions": [
      "The reasoning specifies one or more preceding events or actions, in sequence, as the cause of the observed condition.",
      "The account explains why the current state has the observed properties, not merely what those properties are."
    ],
    "exclusion_conditions": [
      "The reasoning only restates the reported problem or the observed state.",
      "The reasoning lists possible causes without committing to a causal account.",
      "The reasoning merely paraphrases observed output without identifying the preceding events that produced it."
    ]
  },
  {
    "name": "PROPOSES_TESTABLE_HYPOTHESIS",
    "definition": "The reasoning offers a specific but provisional explanation, interpretation, or assumption about an artifact, system state, or cause that is presented as uncertain and can be checked by further observation or action.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node containing the provisional explanation or assumption."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific candidate explanation or interpretation, such as what an artifact might be, why a result occurred, or where a target may reside.",
      "The explanation is presented with uncertainty or as something needing verification rather than as an already established fact."
    ],
    "exclusion_conditions": [
      "The reasoning states only a confirmed conclusion, or repeats an observation without proposing any explanation.",
      "The reasoning contains only a plan of action with no candidate explanation or assumption to test.",
      "The proposed idea is too vague to be checked by any identifiable subsequent observation or action."
    ]
  },
  {
    "name": "ASSESSES_COMPLETENESS_OF_RECOVERY",
    "definition": "The reasoning evaluates the extent to which all recoverable or extractable information has been obtained from the available artifact, justifying a bound on the result by accounting for which data regions were successfully recovered and which are missing, unreadable, or otherwise unavailable.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning that evaluates the completeness and limits of the recovery or extraction."
      }
    ],
    "assertion_conditions": [
      "The reasoning accounts for both the data regions that were recovered and those that are missing, unreadable, or otherwise unavailable.",
      "The reasoning explains why no further recoverable information remains within the available artifact, for example by noting that the remaining region is empty, non-data, or already consumed.",
      "The reasoning concludes a justified bound on the maximum possible recovery."
    ],
    "exclusion_conditions": [
      "The reasoning only reports the final output without evaluating completeness.",
      "The reasoning claims completeness without evidence accounting for unavailable or unexamined data."
    ]
  }
]

Previously Generated Predicate Names:
["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT",
  "definition": "The reasoning explicitly formulates a specific, structured account that organizes information or intended activity into identifiable components and relationships, so that the account can guide or justify a subsequent action, verification, causal explanation, or assessment of a result; it goes beyond merely restating an observation, reporting completed actions, or stating only a vague goal.",
  "parameters": [
    {
      "name": "reasoning",
      "type": "reasoning",
      "description": "The reasoning node that formulates the structured, operative account."
    }
  ],
  "assertion_conditions": [
    "The reasoning explicitly identifies specific content components, such as intended steps, subgoals, causal events, candidate explanations, or recovered and unavailable data regions, rather than only restating an observation or general goal.",
    "The reasoning expresses relevant relationships among those components, such as ordering, dependency, causal sequence, uncertainty requiring verification, or recovered-versus-unavailable coverage, that make the account usable for guidance or justification.",
    "The account is sufficiently specific that at least one subsequent action, check, explanation, or justified result bound can be derived from it."
  ],
  "exclusion_conditions": [
    "The reasoning only reports, summarizes, or paraphrases completed actions, observations, or outputs without formulating a structured account that guides or justifies further action, verification, explanation, or assessment.",
    "The reasoning states only a general goal, desired result, or restated task without identifying specific components or relationships needed to act on or assess it.",
    "The reasoning lists unrelated facts or uncommitted possibilities that do not form an organized, usable account.",
    "The structured content is too vague to support any identifiable subsequent action, check, explanation, or justified result bound."
  ]
}

